result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/test_elasticity.py", "content": "import numpy as np
import pytest

from elasticity import DegeneratePriceError, bootstrap_ci, fit_elasticity, plot_loglog
from gen import generate

TOL_POINT = 0.15


@pytest.fixture(scope="module")
def data():
    return generate()


@pytest.fixture(scope="module")
def result(data):
    prices, units = data
    res = fit_elasticity(prices, units)
    res["ci"] = bootstrap_ci(prices, units)
    return res


def test_point_estimate_close_to_true(result):
    assert abs(result["slope"] - (-1.8)) < TOL_POINT


def test_ci_contains_true_elasticity(result):
    lo, hi = result["ci"]
    assert lo < -1.8 < hi


def test_ci_width_under_0_3(result):
    lo, hi = result["ci"]
    assert (hi - lo) < 0.3


def test_r_squared_above_0_9(result):
    assert result["r_squared"] > 0.9


def test_single_price_raises_clear_error():
    with pytest.raises(DegeneratePriceError, match="[Vv]ariance.*zero|single unique"):
        fit_elasticity([9.99] * 50, np.arange(1, 51) * 100.0)


def test_plot_artist_slope_matches_ols(result):
    line = plot_loglog(result, path="elasticity.png")
    xs = np.asarray(line.get_xdata(), dtype=float)
    ys = np.asarray(line.get_ydata(), dtype=float)
    assert xs.size == ys.size == 2
    artist_slope = (ys[1] - ys[0]) / (xs[1] - xs[0])
    assert artist_slope == pytest.approx(result["slope"], abs=1e-9)
